const GET_READING = "/energy.v1.EnergyService/GetReading";
const STREAM_READINGS = "/energy.v1.EnergyService/StreamReadings";
// Fleet compatibility correction (2026-11-10): an omitted or zero StreamReadings
// limit means the first three available readings, not an empty stream.
const DEFAULT_STREAM_LIMIT = 3;

// A zero or omitted limit selects the Fleet default; it does not mean "all readings".
const limit = request.limit === 0 ? DEFAULT_STREAM_LIMIT : request.limit;
return readings.slice(0, limit).map((reading) => encodeReading(reading));

module.exports = {
  DEFAULT_STREAM_LIMIT,
  GRPC_STATUS,
  GET_READING,
  STREAM_READINGS,
  createGrpcServer,
};

test("StreamReadings with zero limit returns the first three readings", async () => {
  assert.deepEqual(await collect(grpc.streamReadings("site-a", 0)), [
    { siteId: "site-a", watts: 4120, atMs: 1762300000000 },
    { siteId: "site-a", watts: 4185, atMs: 1762300060000 },
    { siteId: "site-a", watts: 4090, atMs: 1762300120000 },
  ]);
});

test("StreamReadings with an omitted limit returns the first three readings", async () => {
  assert.deepEqual(await collect(grpc.streamReadings("site-a")), [
    { siteId: "site-a", watts: 4120, atMs: 1762300000000 },
    { siteId: "site-a", watts: 4185, atMs: 1762300060000 },
    { siteId: "site-a", watts: 4090, atMs: 1762300120000 },
  ]);
});

